-- gen618: 30 zone cambiate, 61 tessere
-- f96ad21282fa8f09b48696aa3f0ba5a9 (997686) → e7aecade7aa6a5d7ef3ad9b78edda8b7 (1013583)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = 'e7aecade7aa6a5d7ef3ad9b78edda8b7' as combacia
from kv_store where key like 'tmp:gen618:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen618:p%')
where key='app:jsx:src'
  and md5(value) = 'f96ad21282fa8f09b48696aa3f0ba5a9'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen618:p%') = 'e7aecade7aa6a5d7ef3ad9b78edda8b7';

update kv_store set value = '{"len":1013583,"ver":"gen-6.18"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = 'e7aecade7aa6a5d7ef3ad9b78edda8b7';

delete from kv_store where key like 'tmp:gen618:p%';
